import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import test from 'node:test';
import { createResolvers } from '../services/catalog/src/resolvers.js';

test('GraphQL resolvers delegate to the repository', async () => {
  const calls = [];
  const repository = {
    listPublished: async () => { calls.push(['list']); return [{ id: 'p1' }]; },
    publish: async (input) => { calls.push(['publish', input]); return { id: 'p2', ...input }; }
  };
  const resolvers = createResolvers(repository);
  assert.deepEqual(await resolvers.Query.products(), [{ id: 'p1' }]);
  const input = { slug: 'lamp', name: 'Lamp', priceCents: 4950, stock: 4 };
  assert.deepEqual(await resolvers.Mutation.publishProduct(null, { input }), { id: 'p2', ...input });
  assert.deepEqual(calls, [['list'], ['publish', input]]);
});

test('schema and migration encode the public and persistence contracts', async () => {
  const schema = await readFile(new URL('../services/catalog/schema.graphql', import.meta.url), 'utf8');
  const sql = await readFile(new URL('../services/catalog/migrations/001_products.sql', import.meta.url), 'utf8');
  assert.match(schema, /type\s+Product/);
  assert.match(schema, /products\s*:/);
  assert.match(schema, /publishProduct/);
  assert.match(sql, /CREATE\s+TABLE/i);
  assert.match(sql, /UNIQUE/i);
  assert.match(sql, /price_cents/i);
  assert.match(sql, /CHECK/i);
});
